"""Baseline: measured outline extruded, holes cut. Generated by baseline_cad.py."""
import cadquery as cq


def build_part(
    thickness=3.0,
    corner1_u=-34.73, corner1_v=-25.18,
    corner2_u=-34.66, corner2_v=25.21,
    corner3_u=34.93, corner3_v=24.91,
    corner4_u=34.33, corner4_v=4.8,
    corner5_u=-14.86, corner5_v=4.91,
    corner6_u=-15.21, corner6_v=-25.21,
    hole1_u=-24.92, hole1_v=-13.28, hole1_diameter=8.01,
    hole2_u=22.81, hole2_v=14.88, hole2_diameter=8.05,
):
    part = cq.Workplane("XY").polyline([(corner1_u, corner1_v), (corner2_u, corner2_v), (corner3_u, corner3_v), (corner4_u, corner4_v), (corner5_u, corner5_v), (corner6_u, corner6_v)]).close().extrude(thickness)
    part = part.cut(cq.Workplane("XY", origin=(hole1_u, hole1_v, -1)).circle(hole1_diameter / 2).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole2_u, hole2_v, -1)).circle(hole2_diameter / 2).extrude(thickness + 2))
    return part
